    stage=c.split('_')[0]; budget=int(c.split('t')[-1]); rag='_rag_' in c
    rows.append(dict(experiment=c,dataset='Pira selected English development subset',split='development (exploratory; previously used for model selection)',questions=101,source_groups=91,alternate_groups=90,answers=101,base_model='Same local Qwen3-4B-Instruct',adapter='none' if stage=='base' else f'outputs/ocean_qwen3_english_grounded_{stage}/epoch_1',stage=stages[stage],rag=rag,retrieval=retr if rag else 'none',generation_budget=budget,prompt='evidence_v2 shared actual same-question prompt/context; greedy; NF4/FP16',metrics='citation-stripped F1; raw F1; words/tokens; EOS/length; valid/invalid/unfinished citations',denominator='101 paired questions per condition; marker totals separate',statistics='paired question-weighted EID-group percentile bootstrap;91 groups (90 merged-passage sensitivity);10000;seed20261028;pointwise unadjusted',raw=str(EV/'dev_supplement_20261028_164300/answers.jsonl'),configuration=str(EV/'dev_supplement_20261028_164300/protocol.json'),evidence_scope='1010 answers from 101 development questions; budget replay diagnostics are not independent replications'))
