dict(experiment='official_AI40',dataset='subset of official test answer_in_text=1',split='preselected AI evaluation subset',questions=40,source_groups=40,alternate_groups=32,answers=160,base_model='same official four conditions',adapter='same final English v2 for FT',stage='base versus final FT',rag='two of four conditions',retrieval=retr,generation_budget=160,prompt='existing formal answers',metrics='AI quality/completeness/faithfulness 0-4; supported citation links; evidence coverage',denominator='160 quality ratings;80 RAG evidence ratings; per-link/per-claim counts',statistics='paired source bootstrap;2000;seed20261018;40 groups/32 sensitivity; excludes judge error',raw=str(EV/'ai_evaluation_adopted_20261018/per_answer_ai_scores.json'),configuration=str(EV/'ai_evaluation_adopted_20261018/report.md'),evidence_scope='One AI evaluation process; no independent human raters; exact judge version unrecorded; separate from dev audit'),
