# Preserve hashes for input artifacts; avoid base model shards and output directory.
paths=set()
for d in ['ai_content_audit_20261028_175905','ai_evaluation_adopted_20261018','dev_supplement_20261028_164300','en_test_mcqa_frozen_v1_20261017','en_test_openqa_frozen_v1_20261017','en_test_mcqa_frozen_v1_report_20261017','en_test_openqa_frozen_v1_report_20261017']:
    paths.update(p for p in (EV/d).rglob('*') if p.is_file() and '__pycache__' not in str(p))
paths.update((ROOT/'paper_data/frozen_english_v1_20261017').glob('*.json'))
paths.update(ROOT/p for p in ['paper_data/正式实验结果汇总.md','paper_data/external_benchmarks/official_english_stage_manifest.json','paper_data/external_benchmarks/official_openqa_en_227.jsonl','paper_data/external_benchmarks/official_mcqa_en_227.jsonl','paper_data/external_benchmarks/dev_openqa_en.jsonl','paper_data/external_benchmarks/corpus_pira_chunks_en.jsonl'])
for v in ['v1','v2']:
    d=ROOT/f'outputs/ocean_qwen3_english_grounded_{v}'
    paths.update(p for p in d.glob('*') if p.is_file() and p.stat().st_size<5_000_000)
hashes=[dict(path=str(p),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(paths) if p.exists()]
pd.DataFrame(hashes).to_csv(OUT/'audit/source_files_sha256.csv',index=False,encoding='utf-8-sig')
